# Note: There's nothing fancy about the compilation flags. It's just optimization and a copy of the flags that, at the time, were in Debian's /usr/share/hardening-includes/hardening.make
# They have nothing to do with the service structure, I just dislike how much of a difference having IDA Pro's decompiler makes for CTF players. At the time, these flags confused IDA enough that you could miss the (only) structure you actually need to understand and "decompile": I was hoping to make usage of the decompiler more _harmful_ than useful.
set -eux
gcc -D_GNU_SOURCE -std=gnu99 -DLINUX -s -O3 -DNDEBUG -march=pentium4 -mtune=core2 -fstack-protector --param ssp-buffer-size=4 -D_FORTIFY_SOURCE=2 -Wformat -Wformat-security -Werror=format-security -fPIE -pie -Wl,-z,relro -Wl,-z,now -o $DESTDIR/usr/ctf/$SERVICE_USER/sillybox_spawner sillybox_spawner.c -DMY_PATH=\"/usr/ctf/$SERVICE_USER\" -m32
gcc -D_GNU_SOURCE -std=gnu99 -DLINUX -s -O3 -DNDEBUG -march=pentium4 -mtune=core2 -fstack-protector --param ssp-buffer-size=4 -D_FORTIFY_SOURCE=2 -Wformat -Wformat-security -Werror=format-security -fPIE -pie -Wl,-z,relro -Wl,-z,now -o $DESTDIR/usr/ctf/$SERVICE_USER/sillybox sillybox.c -lcrypt -DMY_PATH=\"/usr/ctf/$SERVICE_USER\" -m32
gcc -D_GNU_SOURCE -std=gnu99 -DLINUX -s -O3 -DNDEBUG -march=pentium4 -mtune=core2 -fstack-protector --param ssp-buffer-size=4 -D_FORTIFY_SOURCE=2 -Wformat -Wformat-security -Werror=format-security -fPIE -pie -Wl,-z,relro -Wl,-z,now -o $DESTDIR/usr/ctf/$SERVICE_USER/sillybox_timekiller sillybox_timekiller.c -DMY_PATH=\"/usr/ctf/$SERVICE_USER\" -m32
cp README $DESTDIR/usr/ctf/$SERVICE_USER/
